package com.beeboee.magnot.registry;import com.beeboee.magnot.Magnot;import com.beeboee.magnot.item.*;import net.minecraft.item.*;import net.minecraftforge.eventbus.api.IEventBus;import net.minecraftforge.registries.*;public final class MagnotItems{private static final DeferredRegister<Item> ITEMS=DeferredRegister.create(ForgeRegistries.ITEMS,Magnot.MOD_ID);public static final RegistryObject<Item> IRON_DUST=ITEMS.register("iron_dust",()->new AdaptiveIronDustItem(new Item.Properties().tab(ItemGroup.TAB_MATERIALS)));public static final RegistryObject<Item> FERROUS_PASTE=ITEMS.register("ferrous_paste",()->new Item(new Item.Properties().tab(ItemGroup.TAB_MATERIALS)));public static final RegistryObject<FerrousTubeItem> FERROUS_TUBE=ITEMS.register("ferrous_tube",()->new FerrousTubeItem(new Item.Properties().tab(ItemGroup.TAB_TOOLS).stacksTo(1).durability(99)));private MagnotItems(){}public static void register(IEventBus bus){ITEMS.register(bus);}}
